<?php

namespace App\Support\Sprints;

use App\Models\Sprint;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Str;

/**
 * The client's Sprint Design Register (Volume 11, 7,008 Sprints).
 *
 * The data file is generated by database/seeders/Sections/data/sprint-register/build_register.py
 * from the Volume 11 workbook. Rows are stored as arrays in "columns" order and repeated values
 * are stored once under "shared"; rows() returns them decoded as keyed arrays.
 */
class Register
{
    public const SOURCE = 'register-v11';

    public const PATH = 'database/seeders/Sections/data/sprint-register/register.json';

    /** @return array{source: string, count: int, rejected: list<array<string, mixed>>, rows: list<array<string, mixed>>} */
    public static function load(?string $path = null): array
    {
        $doc = json_decode((string) file_get_contents($path ?? base_path(self::PATH)), true, flags: JSON_THROW_ON_ERROR);
        $shared = $doc['shared'];
        $columns = $doc['columns'];

        $rows = [];
        foreach ($doc['rows'] as $values) {
            $row = [];
            foreach ($columns as $i => $column) {
                $value = $values[$i];
                $row[$column] = isset($shared[$column]) && $value !== null ? $shared[$column][$value] : $value;
            }
            foreach (['seo_title', 'meta_description'] as $templated) {
                if (is_string($row[$templated] ?? null)) {
                    $row[$templated] = str_replace('{name}', $row['name'], $row[$templated]);
                }
            }
            $rows[] = $row;
        }

        return ['source' => $doc['source'], 'count' => $doc['count'], 'rejected' => $doc['rejected'], 'rows' => $rows];
    }

    /** Per-tier delivery times (the register gives one time for all tiers, or one per tier). */
    public static function delivery(array $row): array
    {
        $d = $row['delivery'];

        return is_array($d) ? $d : ['basic' => $d, 'standard' => $d, 'premium' => $d];
    }

    /**
     * Client-facing summary. The 4B / 4C "Outcome promise" text names the internal batch
     * ("Batch 4B revenue-priority Sprint for ..."), so those rows use the client problem instead.
     */
    public static function summary(array $row): ?string
    {
        $promise = $row['promise'] ?? null;

        return $promise && ! Str::startsWith($promise, 'Batch ') ? $promise : ($row['problem'] ?? $promise);
    }

    /** @return list<string> */
    public static function split(?string $value, string $separator = ';'): array
    {
        return array_values(array_filter(array_map(fn ($v) => rtrim(trim($v), '.'), explode($separator, (string) $value)), fn ($v) => $v !== ''));
    }

    /** @return list<string> "Founders, SMEs, sales teams and market-entry teams" -> 4 items */
    public static function segments(?string $value): array
    {
        return array_values(array_filter(array_map('trim', preg_split('/,\s*|\s+and\s+/', (string) $value) ?: [])));
    }

    /** Register facts kept on every linked sprint (attributes.design_register). */
    public static function facts(array $row): array
    {
        return array_filter([
            'sprint_id' => $row['code'],
            'sku' => $row['sku'],
            'register_category' => $row['category'],
            'category_letter' => $row['letter'],
            'register_subcategory' => $row['subcategory'],
            'page_family' => $row['family'],
            'page_level' => $row['level'],
            'sprint_type' => $row['raw_type'],
            'commercial_layer' => $row['layer'],
            'batch' => $row['batch'],
            'client_segment' => $row['segment'],
            'prices' => $row['prices'],
            'delivery' => self::delivery($row),
            'add_ons' => self::split($row['addons']),
            'subscription_path' => $row['subscription_path'],
            'retainer_path' => $row['retainer_path'],
            'visual_media' => $row['media'],
            'media_required' => $row['needs_media'],
            'automation_class' => $row['automation'],
            'human_review' => $row['human_review'],
            'risk_tier' => $row['risk'],
            'related' => $row['related'],
            'upsell' => $row['upsell'],
            'cross_sell' => $row['cross_sell'],
            'renewal' => $row['renewal'],
            'seo_title' => $row['seo_title'],
            'meta_description' => $row['meta_description'],
        ], fn ($v) => $v !== null && $v !== []);
    }

    /**
     * Full sprint row for a register Sprint that has no earlier record. Content comes only from
     * the register; the generic sprint template renders it (attributes.template = generic).
     *
     * @return array<string, mixed>
     */
    public static function newSprint(array $row, string $slug): array
    {
        $delivery = self::delivery($row);
        $features = (array) ($row['features'] ?? []);
        $packages = [];
        foreach (Packages::TIERS as $key => $name) {
            $packages[] = array_filter([
                'key' => $key,
                'name' => $name,
                'zar' => $row['prices'][$key],
                'delivery' => $delivery[$key],
                'features' => $features[$key] ?? null,
            ], fn ($v) => $v !== null);
        }

        $deliverables = array_values(array_filter(array_map(fn ($key) => isset($features[$key])
            ? ['title' => Packages::TIERS[$key], 'body' => implode('; ', $features[$key])]
            : null, array_keys(Packages::TIERS))));

        $promise = $row['promise'] ?? null;
        $inputs = array_values(array_filter([
            ($items = self::split($row['intake'])) ? ['title' => 'Information we need', 'icon' => 'clipboard-list', 'items' => $items] : null,
            $row['documents'] ? ['title' => 'Documents', 'icon' => 'file-text', 'items' => [rtrim($row['documents'], '.')]] : null,
        ]));

        $attributes = array_filter([
            'template' => 'generic',
            'source' => self::SOURCE,
            'ideal_for' => self::segments($row['segment']),
            'keywords' => array_values(array_filter([$row['category'], $row['subcategory']])),
            'outcomes' => $promise && ! Str::startsWith($promise, 'Batch ') ? [$promise] : null,
            'included' => array_map(fn ($t) => ['title' => $t], self::split($row['deliverable'])),
            'deliverables' => $deliverables ?: null,
            'package_guidance' => $features ? array_map(fn ($f) => implode('; ', $f), $features) : null,
            'inputs' => $inputs ?: null,
            'qa' => array_values(array_filter([
                $row['risk'] ? ['title' => 'Risk tier', 'body' => $row['risk'], 'icon' => 'shield-check'] : null,
                $row['human_review'] ? ['title' => 'Human review', 'body' => $row['human_review'], 'icon' => 'user-check'] : null,
                $row['automation'] ? ['title' => 'Automation level', 'body' => $row['automation'], 'icon' => 'cpu'] : null,
            ])),
            'billing_period' => in_array($row['act'], ['subscription', 'retainer'], true) ? 'month' : null,
            'design_register' => self::facts($row),
        ], fn ($v) => $v !== null && $v !== []);

        return [
            'code' => $row['code'],
            'register_id' => $row['code'],
            'slug' => $slug,
            'title' => $row['name'],
            'type' => $row['type'],
            'category' => $row['catalogue_category'],
            'subcategory' => $row['category'],
            'page_family' => $row['family'],
            'shop_aisle' => $row['aisle'],
            'audience' => implode(',', $row['audience']),
            'summary' => ($s = self::summary($row)) !== null ? Str::limit($s, 497) : null,
            'description' => $row['problem'],
            'price_zar' => $row['prices']['basic'],
            'delivery' => $delivery['basic'] !== null ? mb_substr($delivery['basic'], 0, 250) : null,
            'commercial_act' => $row['act'],
            'packages' => $packages,
            'attributes' => $attributes,
            'featured' => false,
            'popular' => false,
            'is_new' => false,
            'rating' => null,
            'status' => 'published',
        ];
    }

    /** Distinct register Sprints on the site (cached; rebuilt when the sprints table changes). */
    public static function liveCount(): int
    {
        $version = Sprint::query()->count().'-'.Sprint::query()->max('updated_at');

        return (int) Cache::remember('sprints.register-count.'.md5($version), now()->addDay(), fn () => Sprint::query()
            ->where('status', 'published')->whereNotNull('register_id')->distinct()->count('register_id'));
    }
}
